'use strict';
const groups = [{"id": "lapunta", "number": "01", "title": "La Punta", "timing": "IL NOSTRO ANGOLO · OGNI POMERIGGIO LIBERO", "color": "pink", "description": "Dove dormiamo. Qui è tutto a pochi passi da Sicarú, niente taxi.", "sections": [["SPIAGGIA E TRAMONTO", [["lapuntabeach", "La spiaggia di La Punta", "la punta di Zicatela, onde più gentili e surfisti sulla punta"], ["puntasunset", "Tramonto sulla punta di La Punta", "si gira intorno agli scogli in fondo e si guardano i surfisti", "Il piano del mercoledì."]]], ["CAFFÈ DOPO IL LAVORO", [["lapuntacoffee", "La Punta Coffee", "piccola caffetteria appena fuori dalla via principale: açaí bowl, matcha latte, toast di pasta madre"], ["capsula", "Capsula", "minuscolo bar da asporto di caffè specialty messicano: flat white e latte freddi"], ["sukuun", "Café Suku’un", "espresso bar sulla via principale: smoothie bowl, succhi, caffè freddo e dolci"], ["casakooks", "Casa Kooks", "espresso bar dalle 7:30, famoso per l’espresso tonic e i frullati"], ["blackbaba", "Black Baba", "caffè per bubble tea, cioccolata oaxaqueña e qualcosa da mangiare"]]], ["MANGIARE", [["chicama", "Chicama", "peruviano: ceviche, aguachile e ottimi cocktail; quello che consigliano tutti, e più caro"], ["alalena", "A La Leña", "pizza sottile all’italiana nel forno a legna, fatta dal proprietario"], ["poke", "Poke Surf Club", "poke bowl da comporre con pesce fresco; veloce e conveniente"], ["fishshack", "Fish Shack La Punta", "tacos di mare: gamberi all’aglio, calamari, cavolfiore, e piatti al cocco"], ["nativo", "Nativo", "pesce alla buona: filetti, pescadillas e aguas frescas a prezzi bassi"], ["pepes", "Pepe’s Fish Tacos", "taqueria vivace di pesce e gamberi, con gamberi al cocco e il succo del giorno"]]], ["DA BERE", [["bikini", "Bikini Bar", "cocktail bar con drink serviti nell’ananas, mezcal e musica tranquilla"], ["nodo", "Nodo Brewery", "birreria con tante birre artigianali, cibo da bar, musica dal vivo e una parete d’arrampicata"], ["boneyard", "The Boneyard", "bar accanto a una skate bowl: pizza, hamburger, patatine condite e rock classico"]]], ["SE CI SERVE UNA SCRIVANIA", [["checowork", "Coworking all’ostello Che", "coworking dentro l’ostello Che, con piscina e terrazza; chiedere del pass giornaliero"], ["coworkpuerto", "Cowork Puerto", "coworking in città con internet affidabile per le chiamate"], ["malagua", "Malagua Café", "il posto per le colazioni abbondanti: uova alla Benedict, omelette, buon caffè; c’è gente, il servizio può essere lento"]]]], "note": "Caffè, cibo e coworking non contano nei progressi: spuntali se vuoi."}, {"id": "carrizalillo", "number": "02", "title": "Carrizalillo, Rinconada e le tartarughe", "timing": "UN POMERIGGIO · PERFETTO DI VENERDÌ", "color": "blue", "description": "Un bagno, un pranzo tardi, poi le tartarughine e il tramonto a Bacocho. Tutto vicino, nella parte nord della città.", "sections": [["BAGNO", [["carrizalillobeach", "Playa Carrizalillo", "caletta piccola e riparata, circa 160 gradini", "Abbastanza calma per nuotare. Tieni le forze per risalire."]]], ["PRANZO TARDI A RINCONADA", [["tentate", "Tentate 777", "piccolo caffè-bar per il brunch: colazioni abbondanti, yogurt, brownie"]]], ["TARTARUGHE E TRAMONTO", [["turtles", "Liberazione delle tartarughine a Vive Mar", "su Playa Bacocho, circa 150 pesos, in contanti", "Niente prenotazione. Arrivare entro le 16:45; la liberazione è verso le 18. Dipende da quante uova si sono schiuse quella mattina, quindi chiedere prima sul posto.", [["Su Vive Mar", "https://www.mexicodesconocido.com.mx/liberacion-de-tortugas-recien-nacidas-en-puerto-escondido-una-experiencia-que-jamas-olvidaras.html"]]], ["bacocho", "Tramonto su Playa Bacocho", "spiaggia lunga da passeggio, non per nuotare: le correnti sono forti"]]]], "note": "Finire di lavorare verso le 13 per un bagno vero. Poco tempo? Taglia la spiaggia, non le tartarughe. Chiedi al campo o a un hotel vicino di chiamare un taxi per il ritorno col buio."}, {"id": "lagoon", "number": "★", "title": "Laguna Manialtepec di notte", "timing": "LA PRIMA SERA · GIOVEDÌ", "color": "blue", "description": "In barca sulla laguna al buio, dove ogni scia del remo e ogni mano nell’acqua si accende di blu. Circa 30 minuti a ovest della città, si rientra tardi.", "sections": [["LA LAGUNA CHE BRILLA", [["manialtepec", "Uscita in barca tra la bioluminescenza", "circa 3 ore e mezza con pickup; portare costume e asciugamano", "Roberts Ecotours (la mia scelta): 1.200 pesos a testa con trasporto; si prenota su WhatsApp; pickup a La Punta verso le 18:20. Oppure Civitatis, da circa 42 dollari con cancellazione gratuita, o Lalo Ecotours, la cui uscita notturna va dalle 20 alle 22.", [["Roberts Ecotours su WhatsApp", "https://wa.me/5219541083547"], ["Tour della laguna di Roberts Ecotours", "https://robertsecotours.com/tours/bioluminescent-lagoon/"], ["Tour notturno su Civitatis", "https://www.civitatis.com/en/puerto-escondido/night-tour-manialtepec-lagoon"], ["Lalo Ecotours", "https://yumping.com/en/water-sports/lalo-eco-tours--e19664927"]]]]]], "note": "La notte più buia del nostro soggiorno: tre giorni dopo la luna nuova, una falce sottile (circa 5%) che tramonta verso le 20:35. Roberts passa a prenderci a La Punta verso le 18:20, quindi è da prenotare per il giorno dell’arrivo. Il bagliore varia e non è mai garantito."}, {"id": "angelito", "number": "03", "title": "Puerto Angelito e Manzanillo", "timing": "L’ULTIMO POMERIGGIO · GIOVEDÌ", "color": "green", "description": "Due piccole baie calme una accanto all’altra, perfette per nuotare e fare snorkeling.", "sections": [["DUE CALETTE", [["angelitobeach", "Playa Puerto Angelito", "acqua calma, barche e ristorantini sulla spiaggia"], ["manzanillo", "Playa Manzanillo", "accanto, pochi passi sugli scogli"]]]], "note": "Meno gradini di Carrizalillo, e un ultimo bagno facile prima di fare le valigie. Meglio tornare prima che faccia buio."}, {"id": "town", "number": "04", "title": "In città", "timing": "QUANDO ABBIAMO VOGLIA DI CAMBIARE", "color": "pink", "description": "La città vera, dieci minuti più su lungo la strada costiera.", "sections": [["UN GIRETTO", [["mercado", "Mercado Benito Juárez", "il mercato della città: frutta, succhi e pranzi economici"], ["adoquin", "El Adoquín", "la via pedonale sulla baia principale, con l’ufficio turistico"], ["binisa", "Café Binisa", "caffè locale per caffè freddo, filtro e cappuccino; niente wifi"]]]], "note": "I colectivos percorrono la strada costiera per circa 8–12 pesos."}, {"id": "mazunte", "number": "SAB", "title": "Mazunte e Punta Cometa", "timing": "LA NOSTRA GRANDE GITA · UN SABATO INTERO", "color": "pink", "weekend": true, "description": "La spiaggia di un paesino, il centro delle tartarughe, un’occhiata a San Agustinillo e Zipolite, poi il tramonto dal promontorio. Circa un’ora più giù lungo la costa.", "table": {"caption": "Come arrivare a Mazunte", "map": "Mappa", "days": [["Tour · pickup e rientro in hotel", [["10–19", "★ Experiencias Nativas · la mia scelta", "Mazunte, Zipolite e il tramonto a Punta Cometa, con il ritorno già organizzato. Circa 60 € a testa.", "Pickup a Puerto Escondido", "Mazunte Oaxaca", "https://www.ebookers.ie/things-to-do/mazunte-ventanilla-and-zipolite-ecotour.a52131871.activity-details"], ["9–20:30", "Ocean Travel · da Estacahuite a Punta Cometa", "Prima snorkeling a Estacahuite, poi Mazunte e tramonto. Da 1.369 pesos a testa.", "Pickup a Puerto Escondido", "Playa Estacahuite Oaxaca", "https://oceantravel.nodo5.com/en/en-que-plan-viajas/detalles/desde-puerto-escondido-estacahuite-a-punta-cometa-un-dia-de-aventura-costera"], ["Circa 10 ore", "GetYourGuide · gita a Mazunte e Zipolite", "Centro delle tartarughe, Zipolite e tramonto a Punta Cometa. Cibo e ingresso a Punta Cometa a parte.", "Pickup a Puerto Escondido", "Centro Mexicano de la Tortuga Mazunte", "https://www.clicatour.com/en/excursion/mexico/oaxaca/puerto-escondido-dagtour-mazunte-en-zipolite-1742676412"]]], ["Taxi · con i nostri tempi", [["Tutto il giorno", "Taxi o autista per la giornata", "Niente gruppo. 1.300–1.600 pesos andata e ritorno in due con attesa, o 800–1.100 solo andata. Fissare prima l’ora del ritorno.", "Circa un’ora a tratta", "Mazunte Oaxaca"]]], ["Scooter · solo con la luce", [["Rientro prima del buio", "Noleggiare uno scooter", "Circa 500 pesos al giorno; in due sullo stesso, con il casco. Rientro prima del buio, quindi niente tramonto a Punta Cometa. Controllare che l’assicurazione di viaggio lo copra.", "67 km a tratta sulla Highway 200", "Mazunte Oaxaca"]]], ["Autobus · il più economico", [["2–3 ore", "Autobus, poi colectivo da Pochutla", "Circa 210 pesos a testa a tratta. Facile all’andata; scomodo al ritorno dopo il tramonto.", "Cambio a Pochutla", "Pochutla Oaxaca"]]]]}, "sections": [["A MAZUNTE", [["mazuntebeach", "Paese e spiaggia di Mazunte", "pranzo, un bagno e una passeggiata"], ["tortuga", "Centro Mexicano de la Tortuga", "il centro nazionale delle tartarughe sulla collina"]]], ["LUNGO LA COSTA", [["sanagustinillo", "San Agustinillo", "piccola baia di paese tra Mazunte e Zipolite, buona per un bagno"], ["zipolite", "Zipolite", "la spiaggia lunga e selvaggia subito dopo"]]], ["TRAMONTO", [["puntacometa", "Punta Cometa", "breve salita sul promontorio; andare 45 minuti prima del tramonto"]]]], "note": "Comunque andiamo, organizziamo il ritorno prima di partire: non c’è Uber e a Mazunte, col buio, i taxi sono rari."}];
const optional = [["dolphins", "Uscita in barca tra delfini e tartarughe", "una mattina presto, circa 3 ore", "Roberts Ecotours: 3 ore e mezza dalle 6:30, maschera e pickup inclusi. Le balene a metà novembre sono improbabili.", [["Roberts Ecotours", "https://www.robertsecotours.com/"], ["Eco Adventures", "https://wildlifenomads.com/find-a-wildlife-guide-tour/eco-adventures-puerto-escondido"]]], ["horseride", "A cavallo fino alle terme di Atotonilco", "una mattina presto, circa 4–5 ore", "Eco Adventures (meglio il turno delle 6), Experiencias Nativas o Lalo Ecotours. Solo di mattina: più tardi i fiumi si alzano.", [["Experiencias Nativas", "https://www.viator.com/en-GB/tours/Puerto-Escondido/Horses-in-Manialtepec/d23875-116123P1"], ["Eco Adventures", "https://wildlifenomads.com/find-a-wildlife-guide-tour/eco-adventures-puerto-escondido"], ["Lalo Ecotours", "https://yumping.com/en/water-sports/lalo-eco-tours--e19664927"]]], ["surf", "Una lezione di surf per principianti", "nel tardo pomeriggio a La Punta, circa 600–1.000 pesos", "", [["Lezioni di surf per principianti", "https://www.clicatour.com/en/excursion/mexico/oaxaca/surflessen-in-puerto-escondido"]]]];
const KEY='frolicking-nicky-puerto-escondido-v1';
let checked={}; let storageOK=true;
try { const saved=JSON.parse(localStorage.getItem(KEY)||'{}'); if(saved && typeof saved==='object' && !Array.isArray(saved)) checked=saved; } catch {storageOK=false;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const OPTIONAL_IDS=new Set(["lapuntacoffee", "capsula", "sukuun", "malagua", "casakooks", "blackbaba", "chicama", "alalena", "poke", "fishshack", "nativo", "boneyard", "bikini", "nodo", "checowork", "coworkpuerto", "binisa", "pepes", "tentate"]);
const countedIds=()=>groups.filter(()=>true).flatMap(g=>g.sections.flatMap(s=>s[1].map(r=>r[0]))).filter(id=>!OPTIONAL_IDS.has(id));
function item(row,extra=false) {const [id,title,desc,note,links]=row;return `<label class="task${checked[id]===true?' completed':''}"><input type="checkbox" id="${esc(id)}" data-extra="${extra}" ${checked[id]===true?'checked':''}><span class="checkmark" aria-hidden="true"></span><span class="task-copy"><span class="task-title">${esc(title)}</span> <span class="specialty">(${esc(desc)})</span>${note?`<span class="task-note">${esc(note)}</span>`:''}${links&&links.length?`<span class="fn-task-links">${links.map(([l,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(l)} ↗︎</a>`).join('')}</span>`:''}</span></label>`;}
const PHOTOS={"lapunta": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Surf_at_Sunset_-_Zicatela_Beach_-_Puerto_Escondido_-_Oaxaca_-_Mexico_%286533419239%29.jpg/1280px-Surf_at_Sunset_-_Zicatela_Beach_-_Puerto_Escondido_-_Oaxaca_-_Mexico_%286533419239%29.jpg", "Surfisti su un’onda dorata al tramonto a Zicatela", 1280, 960, "Adam Jones", "CC BY-SA 2.0", "https://commons.wikimedia.org/wiki/File:Surf_at_Sunset_-_Zicatela_Beach_-_Puerto_Escondido_-_Oaxaca_-_Mexico_(6533419239).jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Coconut_Puerto_Escondido.jpg/1280px-Coconut_Puerto_Escondido.jpg", "Una noce di cocco fresca con la cannuccia su un tavolo di legno blu, accanto a una birra e un piattino di lime e peperoncino", 1280, 960, "subzonica", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Coconut_Puerto_Escondido.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Pescado_Puerto_Escondido.jpg/1280px-Pescado_Puerto_Escondido.jpg", "Un pesce intero alla griglia con riso, insalata di avocado e lime sulla spiaggia di Zicatela", 1280, 960, "darij", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Pescado_Puerto_Escondido.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/b/be/Los_Tios_Puerto_Escondido.jpg/1280px-Los_Tios_Puerto_Escondido.jpg", "L’insegna al neon verde di Los Tios che brilla nel buio a Zicatela", 1280, 1920, "arvindgrover", "CC BY-SA 2.0", "https://commons.wikimedia.org/wiki/File:Los_Tios_Puerto_Escondido.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/b/b5/Beach_Restaurant_Playa_Zicatela.jpg", "Un cocktail con il lime su una tovaglia a quadri sotto gli ombrelloni gialli a Zicatela", 1024, 683, "StellarD", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Beach_Restaurant_Playa_Zicatela.jpg"]]], "carrizalillo": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Playa_Carrizalillo_Puerto_Escondido.jpg/1280px-Playa_Carrizalillo_Puerto_Escondido.jpg", "La piccola caletta riparata di Playa Carrizalillo tra scogliere verdi", 1280, 851, "elfidomx", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Playa_Carrizalillo_Puerto_Escondido.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/Playa_Carrizalillo%2C_Puerto_Escondido.jpg/1280px-Playa_Carrizalillo%2C_Puerto_Escondido.jpg", "La vista dal sentiero sulla scogliera verso l’acqua turchese di Carrizalillo", 1280, 1707, "Axolotesonriente", "CC0", "https://commons.wikimedia.org/wiki/File:Playa_Carrizalillo,_Puerto_Escondido.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Olive_ridley_hatchling_in_Mexico_%288218893828%29.jpg/1280px-Olive_ridley_hatchling_in_Mexico_%288218893828%29.jpg", "Una tartarughina olivacea sulla sabbia bagnata", 1280, 1073, "Steve Jurvetson", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Olive_ridley_hatchling_in_Mexico_(8218893828).jpg"]]], "lagoon": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Laguna_de_Manialtepec_Oaxaca.jpg/1280px-Laguna_de_Manialtepec_Oaxaca.jpg", "Mangrovie lungo l’acqua ferma della Laguna Manialtepec", 1280, 960, "Lunita28mx", "CC BY 4.0", "https://commons.wikimedia.org/wiki/File:Laguna_de_Manialtepec_Oaxaca.jpg"], ["https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/Pelicanos_en_la_laguna_Manialtepec.JPG/1280px-Pelicanos_en_la_laguna_Manialtepec.JPG", "Pellicani appollaiati sui rami sopra la Laguna Manialtepec", 1280, 852, "Jaumahell", "CC BY-SA 3.0", "https://commons.wikimedia.org/wiki/File:Pelicanos_en_la_laguna_Manialtepec.JPG"]]], "angelito": [[["https://upload.wikimedia.org/wikipedia/commons/4/41/Puerto_Angelito%2C_Oaxaca._-_panoramio.jpg", "Barche e bagnanti nella baia tranquilla di Puerto Angelito", 1000, 654, "holachetumal", "CC BY 3.0", "https://commons.wikimedia.org/wiki/File:Puerto_Angelito,_Oaxaca._-_panoramio.jpg"]]], "town": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/PUERTO_ESCONDIDO.JPG/1280px-PUERTO_ESCONDIDO.JPG", "Il tramonto sulle barche e sui bagnanti nella baia principale di Puerto Escondido", 1280, 960, "Oescalona", "CC BY-SA 3.0", "https://commons.wikimedia.org/wiki/File:PUERTO_ESCONDIDO.JPG"]]], "mazunte": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/Mazunte_beach_from_the_Turtle_Center.jpg/1280px-Mazunte_beach_from_the_Turtle_Center.jpg", "La spiaggia di Mazunte vista dal centro delle tartarughe sulla collina", 1280, 960, "Tvdp77", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Mazunte_beach_from_the_Turtle_Center.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/ZipoliteFromAmor.JPG/1280px-ZipoliteFromAmor.JPG", "La lunga curva della spiaggia di Zipolite vista dalla collina", 1280, 857, "AlejandroLinaresGarcia", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:ZipoliteFromAmor.JPG"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Punta_Cometa%2C_Mazunte%2C_Oaxaca.jpg/1280px-Punta_Cometa%2C_Mazunte%2C_Oaxaca.jpg", "Il promontorio erboso di Punta Cometa sopra il Pacifico", 1280, 853, "Anna Bertho", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Punta_Cometa,_Mazunte,_Oaxaca.jpg"]]]};
const fig=([src,alt,w,h,by,lic,url])=>`<figure class="fn-v-photo"><a href="${src}" target="_blank" rel="noopener"><img src="${src}" alt="${esc(alt)}" width="${w}" height="${h}" loading="lazy"></a></figure>`;
const muertosTable=t=>{const pick=(()=>{const d=new Date();const k=(d.getMonth()+1)*100+d.getDate();return {1031:1,1101:2,1102:3}[k]??0;})();return `<div class="fn-plan-tabs" role="tablist" aria-label="${esc(t.caption)}">${t.days.map(([day],i)=>`<button type="button" role="tab" id="fn-plan-tab-${i}" aria-controls="fn-plan-day-${i}" aria-selected="${i===pick}" tabindex="${i===pick?0:-1}">${esc(day.split(' · ')[0])}</button>`).join('')}</div>${t.days.map(([day,rows],i)=>`<div class="fn-plan-panel" role="tabpanel" id="fn-plan-day-${i}" aria-labelledby="fn-plan-tab-${i}"${i===pick?'':' hidden'}>${day.includes(' · ')?`<p class="fn-plan-sub">${esc(day.split(' · ').slice(1).join(' · '))}</p>`:''}<ol class="fn-plan-stops">${rows.map(([when,plan,what,where,q,url])=>`<li${/★/.test(plan)?' class="fn-plan-star"':''}><span class="fn-plan-when">${esc(when)}</span><div><p class="fn-plan-name">${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(plan)} ↗︎</a>`:esc(plan)}</p><p class="fn-plan-what">${esc(what)}</p><p class="fn-plan-where">${esc(where)} <a class="fn-plan-map" href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent(q)}" target="_blank" rel="noopener noreferrer">${esc(t.map)}</a></p></div></li>`).join('')}</ol></div>`).join('')}`;};
let rowN=0;
document.querySelector('#itinerary').innerHTML=groups.map(g=>`<section id="${g.id}" class="outing fn-split ${g.color} ${g.weekend?'weekend':''}" aria-labelledby="title-${g.id}"><div class="outing-heading"><span class="number" aria-hidden="true">${g.number}</span><div><p class="eyebrow">${g.timing}</p><h2 id="title-${g.id}">${g.title}</h2><p class="section-desc">${g.description}</p></div><span class="group-count" id="count-${g.id}" aria-label="Completamento della sezione"></span></div>${g.table?`<div class="fn-plan-wrap">${muertosTable(g.table)}</div>`:''}<div class="outing-body fn-split-body"${g.sections.length?'':' hidden'}>${g.sections.map(([title,rows],si)=>{const ps=(PHOTOS[g.id]||[])[si]||[];const card=`<div class="task-group"><h3>${title}</h3>${rows.map(r=>item(r,OPTIONAL_IDS.has(r[0]))).join('')}</div>`;return ps.length?`<div class="fn-v-row${rowN++%2?' fn-v-rev':''}"><div class="fn-v-side">${ps.map(fig).join('')}</div>${card}</div>`:card;}).join('')}</div><div class="outing-note"><p>${g.note}</p>${g.link?`<a href="${g.link[1]}" target="_blank" rel="noopener noreferrer">${g.link[0]} ↗︎</a>`:''}</div></section>`).join('');
document.querySelectorAll('.fn-plan-tabs').forEach(list=>{const tabs=[...list.querySelectorAll('[role=tab]')];const show=(tab,focus)=>{tabs.forEach(b=>{const on=b===tab;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;document.getElementById(b.getAttribute('aria-controls')).hidden=!on;});if(focus)tab.focus();};tabs.forEach((b,i)=>{b.addEventListener('click',()=>show(b));b.addEventListener('keydown',e=>{const n={ArrowRight:i+1,ArrowLeft:i-1,Home:0,End:tabs.length-1}[e.key];if(n===undefined)return;e.preventDefault();show(tabs[(n+tabs.length)%tabs.length],true);});});});
document.querySelector('#optional-list').innerHTML=optional.map(r=>item(r,true)).join('');
function update(announce=false){const mainIds=countedIds();const done=mainIds.filter(id=>checked[id]===true).length;const percent=Math.round(done/mainIds.length*100);document.querySelector('#progress-count').textContent=done;document.querySelector('#progress-total').textContent=`su ${mainIds.length} posti e momenti`;document.querySelector('#percent').textContent=percent+'%';document.querySelector('#progress').value=percent;document.querySelector('#progress').textContent=percent+'%';groups.forEach(g=>{const inactive=false;const ids=g.sections.flatMap(s=>s[1].map(r=>r[0])).filter(id=>!OPTIONAL_IDS.has(id));document.querySelector('#count-'+g.id).hidden=!ids.length;document.querySelector('#count-'+g.id).textContent=inactive?"Alternativa: non conta nella checklist":`${ids.filter(id=>checked[id]===true).length} / ${ids.length}`;});const extra=[...optional.map(r=>r[0]),...OPTIONAL_IDS].filter(id=>checked[id]===true).length;document.querySelector('#extra-count').textContent=`${extra} ${extra===1?'tappa facoltativa fatta':'tappe facoltative fatte'}`;document.querySelector('#save-note').textContent=storageOK?'Progressi salvati su questo dispositivo.':'Le spunte funzionano qui, ma in questo browser il salvataggio non è disponibile.';if(announce)document.querySelector('#announcement').textContent=`${done} su ${mainIds.length} voci principali completate. ${extra} tappe facoltative fatte.`;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(checked));storageOK=true;}catch{storageOK=false;}}
document.addEventListener('change',e=>{if(!e.target.matches('.task input'))return;checked[e.target.id]=e.target.checked;e.target.closest('.task').classList.toggle('completed',e.target.checked);persist();update(true);});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{const next=JSON.parse(e.newValue||'{}');checked=next&&typeof next==='object'&&!Array.isArray(next)?next:{};}catch{checked={};}document.querySelectorAll('.task input').forEach(el=>{el.checked=checked[el.id]===true;el.closest('.task').classList.toggle('completed',el.checked);});update();});
const dialog=document.querySelector('#reset-dialog');document.querySelector('#reset').addEventListener('click',()=>dialog.showModal());document.querySelector('#cancel-reset').addEventListener('click',()=>dialog.close());document.querySelector('#confirm-reset').addEventListener('click',()=>{checked={};persist();document.querySelectorAll('.task input').forEach(el=>{el.checked=false;el.closest('.task').classList.remove('completed');});update(true);dialog.close();});
update();
